// ── sumerians.siege.js
// The fall of Ur (c. 2004 BCE) and the Lament for Ur sung over it, with the lyre and the kettle drum. Its music is lost; the mode and singing follow Peter Pringle's reconstructed Sumerian laments on a replica of the Lyre of Ur.
SCORES["sumerians:siege"] = {
  about: "the siege and fall of Ur: the attackers' drums and cries outside the walls, the starving city wailing, the temple of Nanna burning; then the gala singer and the women lament alas, my city, alas, my house to the lyre and the kettle drum",
  heard: "inside the walls of Ur: the enemy's drums and shouts from beyond the wall, people crying in the streets, the temple roof burning; afterwards in the burnt court a single lament singer with a lyre and the drum, and the women's voices answering",
  refs: [
    { title: "Lament for Gilgamesh, the Gold Lyre of Ur", who: "Peter Pringle, voice and a replica of the lyre of Ur, sung in Sumerian", url: "https://www.youtube.com/watch?v=dDRD3c-WAec" },
    { title: "Hurrian Hymn no. 6 (c. 1400 BCE)", who: "Michael Levy, reconstructed lyre (the nearest notated music of the region)", url: "https://www.youtube.com/watch?v=64aouN2oohM" },
  ],
  measured: "The siege before the lament (attackers' frame drums and cries, the city wailing, the walls battered, the fire) is scene sound, not taken from any recording. Uncertain: no Sumerian melody survives; the Lament for Ur's words do (ETCSL), the sung words here are only lament refrain words (a, alas; uru₂-ĝu₁₀, my city; e₂-ĝu₁₀, my house; a-še-er, sighing), not a quotation. The instruments are real (lyres like the ones excavated at Ur, the lilis kettle drum and the balag of the gala lamenters); the mode follows Pringle's reconstruction rather than evidence. Measured in Pringle's lament: resting on C with a lowered second (80 c) and notes about 390, 480, 680, 780, 990 c, very long held notes (3–5 s) with ~12 c vibrato and slides (glides 0.17), half a note a second, C3–B4, 125–500 Hz. Ours: scale@lament with those cents; the melody rebuilt from his note sequence; rendered: most used note F as in the reference, ~14 c vibrato, 0.9 notes a second, 250–500 Hz peak, the same cents within 30 c. Pyin against Pringle: his voice glides 24% of the time and joins most notes slowly (58% slower than 80 ms), with held notes shaking ±12 cents; the gala and the women now slide through much of each note (glide=0.8, a light scoop) and its vibrato is narrower (vib=0.016): ours alone gives 12% gliding (before 8%), joins slower than 80 ms 67%, and ±20 cents (before ±30). Still differs: his slides are longer and cover more of each note than ours; the lyre is the engine's generic harp string, not the bull-headed lyre's box",
  text: `
. clock        60 4/4
. arrange@song siege:6bars fall:4bars lament:11bars ningal:11bars
. scale@lament 1 2:80 3:390 4:480 5:680 6:780 7:990
. key          lament C

. caption@urim "𒋀𒀊𒆠 · 𒀭𒊩𒌆𒃲" ?song.3-4
. wind@dust    0.2 gust=0.1Hz
. drums@attackers kit=daf vol=0.7 "X.....x.X.....x.|..x...x...x...x.|................" ?song.1-2
. crowd@outside shout "o-HA a-HA" "x-x-............................x---............................" voices=30 voice=men vol=1.4 dyn="mp mf f" ?song.1-2
. crowd@city   ululate "a-a-a" "x-------........" voices=12 voice=women vol=0.9 ?song.1-2
. drums@walls  kit=work vol=0.6 "................|X.......X.......|................" ?song.2
. fire@temple  0.18 crackle=0.5 ?song.2-4
. timpani@lilis oct=2 grid=8 human=0.4 vol=0.8 "1 - - - - - - - 0 0 0 0 1 - 1 -" ?song.3-4
. pluck@lyre-of-ur oct=3 grid=8 human=0.5 rubato=0.3 vol=1.4 "1+5 - - - 4 - 3 - 1+5 - - - 2 - 1 -" ?song.3-4
. chant@gala   voice=men oct=3 grid=8 human=0.5 rubato=0.4 vib=0.016 breath=0.2 bright=0.35 glide=0.8 scoop=40 dyn="f mf f f mf f mf mf f mf mp" ipa="a u ɾu ŋu a e ŋu a ʃe eɾ ŋu a a u ɾu ŋu a e ŋu a ʃe eɾ ŋu a a u ɾu ŋu a e ŋu a ʃe eɾ ŋu a" "4 - - - - - - 3 4 4 - 3 4 3 - - 2 4 - - - - - - - 3 3 - - - 2 2 1 2 - - - - - - - - - 0 - 1 1 1 2 1 7, - 7 6 7 6 5 6, - - - 6, 5, - 6, - 4, 5, - - 5, - 5, - - - - 3, 4, - - - 0 - - - 0 0" ?song.3-4
. chant@women  voice=women voices=8 oct=4 grid=8 human=0.6 rubato=0.4 vib=0.035 breath=0.3 vol=0.55 glide=0.8 scoop=60 dyn="mp" ipa="a u ɾu ŋu a e ŋu a ʃe eɾ ŋu a a u ɾu ŋu a e ŋu a ʃe eɾ ŋu a a u ɾu ŋu a e ŋu a ʃe eɾ ŋu a" "4 - - - - - - 3 4 4 - 3 4 3 - - 2 4 - - - - - - - 3 3 - - - 2 2 1 2 - - - - - - - - - 0 - 1 1 1 2 1 7, - 7 6 7 6 5 6, - - - 6, 5, - 6, - 4, 5, - - 5, - 5, - - - - 3, 4, - - - 0 - - - 0 0" ?song.4

*> space       courtyard size=1.6 wet=0.25
>  speaker     0.5
`,
};

