// ── wei.triumph.js
// 觀滄海: Cao Cao's verses at Jieshi (207), sung by the army on the way home by the sea. The Han–Wei tune is lost; the line
// follows the traditional chanted recitation (吟诵) of the poem in Qian Shaowu's (錢紹武) recitation tune, measured with refs/analyse.py.
{
  // On E with the Tang-and-later seven-note scale the reciter uses (E F# G# A B C# D, 燕乐). One token an eighth, ♩ = 58.
  const A = "7 - 4 - 1' - - - 3' - - - 2' - - -", B = "1' - 5 - 6 1' 4 - 3 - - - - - - -";     // odd couplets
  const A2 = "5 - 6 - 1' - - - 7 - 3' - - - - -", B2 = "3' - 2' 1' 5 - - - 4 - 3 - 1 - - -";  // even couplets
  const odd = `${A} ${B}`, even = `${A2} ${B2}`;
  const c = [
    "toŋ lin tɕie ʂɨ _ i kuan tsʰaŋ _ xai _",          // 東臨碣石，以觀滄海
    "ʂuei xɤ tan tan _ ʂan tau _ suŋ _ _ tʂɨ",         // 水何澹澹，山島竦峙
    "ʂu mu tsʰuŋ ʂəŋ _ pai tsʰau fəŋ _ mau _",         // 樹木叢生，百草豐茂
    "tɕʰiou fəŋ ɕiau sɤ _ xuŋ po _ yŋ _ _ tɕʰi",       // 秋風蕭瑟，洪波湧起
    "ʐɨ ye tʂɨ ɕiŋ _ ʐuo tʂʰu tɕʰi _ tʂuŋ _",          // 日月之行，若出其中
    "ɕiŋ xan tsʰan lan _ ʐuo tʂʰu _ tɕʰi _ _ li",      // 星漢燦爛，若出其裏
    "ɕiŋ ʂən tʂɨ tsai _ kɤ i yŋ _ tʂɨ _",              // 幸甚至哉，歌以詠志
  ];
  SCORES["wei:triumph"] = {
    about: "Viewing the Blue Sea (觀滄海): on the march home from White Wolf Mountain, by the Bohai at Jieshi, one soldier chants Cao Cao's verses over the surf, and then the whole column takes them up with the drums and reed pipes of the army band",
    heard: "a headland above the sea in autumn: the wind off the water, waves breaking below, a horn sounding the halt; a man's voice chanting slowly, free in time, then the soldiers singing together in unison while the drums of the army band (鼓吹) keep the step and the jia reed pipes double the tune",
    refs: [
      { title: "古詩吟誦《觀滄海》(曹操), 錢紹武先生吟誦調", who: "盛榮芳, chanted recitation (吟诵)", url: "https://www.youtube.com/watch?v=XaE-s29WiSw" },
    ],
    measured: "recitation: comes home to E (tuned ~30 cents flat), uses E F# G# A B C# D with a G natural now and then, G3–G#4, vibrato ~14 cents, one note in six slides, slow and free (pulse clarity 0.14; long notes of 1–4 s at line ends), bright voice (2.1 kHz centroid, strong 250 Hz–4 kHz). Our line keeps that resting tone, scale, range and the shape of its two recurring line-tunes, set to eighths at ♩ = 58 with rubato; words in Mandarin. The Han–Wei yuefu melody is lost; the army band and the soldiers' singing are our setting. Render of the solo: home on E, range G3–G#4 exactly as the reciter, vibrato ~12 cents; darker than him (1.3 kHz centroid against 2.1 at bright=0.45, so we raised the voice's ring to 0.7) with the sea adding low rumble under 250 Hz. Voice gestures: the reciter's slides are short (~0.09 s), so the soldier glides only lightly (glide=0.15, 0.18 s); the massed army sings a little pressed (press=0.2), as men shout-sing in the open; the jiao is now the natural-horn bell blown forte (dyn=f), raw and wavering rather than a trumpet. Our solo voice still has wider vibrato on held notes than the reciter",
    text: `
. clock        58 4/4
. arrange@song sea:2bars cao:16bars army:12bars
. key          yanyue E

. caption@c1   "東臨碣石，以觀滄海。水何澹澹，山島竦峙。 / 樹木叢生，百草豐茂。秋風蕭瑟，洪波湧起。" ?song.2
. caption@c2   "日月之行，若出其中；星漢燦爛，若出其裏。 / 幸甚至哉，歌以詠志。" ?song.3
. water@sea     0.45 lap=0.7 splash=0.15
. wind@autumn   0.3 gust=0.09Hz
. brass@jiao    oct=3 grid=4 vol=0.4 bell=natural dyn="f mf" "1 - - - 5, - 1 -" ?song.1
. chant@soldier voice=men oct=3 grid=8 human=0.5 rubato=0.35 glide=0.15 vib=0.025 breath=0.12 bright=0.7 dyn="mf mf f mf mf f mf mf f mf mf f mf mf f mf" ipa="${c.slice(0, 4).join(" ")}" "${[odd, even, odd, even].join(" ")}" ?song.2
. chant@army    voice=men voices=12 oct=3 grid=8 human=0.6 glide=0.1 press=0.2 vib=0.015 breath=0.15 dyn="f" ipa="${c.slice(4).join(" ")}" "${[odd, even, odd].join(" ")}" ?song.3
. reed@jia      oct=4 grid=8 vol=0.3 dyn="mf" "${[odd, even, odd].join(" ")}" ?song.3
. drums@gu      kit=zhangu vol=0.35 "X.......x.......|....x.......x...|................" ?song.3

*> space       field size=1.2
>  speaker      0.5
`,
  };
}

// ── wei.winter.js
// 苦寒行: Cao Cao's song of the winter march over the Taihang (206), sung by a soldier on the road. The Wei tune (瑟调 of the
// qingshang repertoire) is lost; the line follows the old-style-verse chanting tune (古體詩吟誦調), measured with refs/analyse.py.
{
  // Gong pentatonic on F# (F# G# A# C# D#) with the B the reciter touches; one token an eighth, ♩ = 72.
  const P = "6 - 5 - 5~6 - 2 - 1 - - - - - - -";          // a line falling home
  const Q = "6 - 6 - 1' 1' 6 5 4 3 2 - - - - -";        // a line rising, then running down
  const R = "2 - 4 5 6~5 - 3 2~1 - - - - - - -";          // the answering line, home to 1
  const tune = [P, R, Q, R, P, R, Q, R].join(" ");       // four couplets, 16 bars
  const words = [
    "pei ʂaŋ tʰai xaŋ ʂan", "tɕian tsai _ xɤ wei _ wei",          // 北上太行山，艱哉何巍巍
    "iaŋ tʂʰaŋ pan _ tɕie _ _ _ tɕʰy", "tʂʰɤ lun _ wei tʂɨ _ tsʰuei", // 羊腸坂詰屈，車輪為之摧
    "ʂu mu xɤ ɕiau sɤ", "pei fəŋ _ ʂəŋ tʂəŋ _ pei",             // 樹木何蕭瑟，北風聲正悲
    "ɕyŋ pʰi tuei _ wo _ _ _ tsun", "xu pau _ tɕia lu _ tʰi",     // 熊羆對我蹲，虎豹夾路啼
  ].join(" ");
  SCORES["wei:winter"] = {
    about: "Bitter Cold (苦寒行): on the frozen road through the Taihang mountains a soldier sings Cao Cao's song of the north wind, the bears and tigers by the road and the men with no wood and no shelter, and the men near him hum along",
    heard: "a mountain road in deep winter: the north wind howling down the gorge, the column trudging, a drum keeping a slow step, now and then a horse; one tired voice sings, slow and sliding, the valley sending it back, and the men around him join in low on the line ends",
    refs: [
      { title: "樂府詩吟誦《龜雖壽》(曹操, from the same 步出夏門行 cycle) in the 古體詩吟誦調", who: "邱鳳娟, chanted recitation (吟诵)", url: "https://www.youtube.com/watch?v=Dnko71qeJVg" },
    ],
    measured: "recitation in the old-style-verse tune: home on F#, pitch set F# G# A# B C# D# (gong pentatonic with the 4th as a passing note), F3–E4, a wide vibrato (~19 cents) and a slide on one note in five, ~143 eighths a minute, energy 125–500 Hz (1.5 kHz centroid). We use that scale, pace, range and sliding, with two falling-and-rising line tunes of our own built from its contour, in Mandarin. No recording of 苦寒行 being chanted was found, so a poem of the same cycle stands in; the qingshang tune Cao Cao's court used is lost. Render: range F3–D#4 (reciter F3–E4), brightness 1.50 kHz against 1.47, vibrato ~14 cents and glides on one note in seven against 19 cents and one in five, pace ~136 eighths with rubato against ~143; the howling wind and the valley make ours wetter than the dry studio reference, on purpose. Voice gestures (pyin on the recitation): slides of ~0.2 s between notes; the soldier now glides (glide=0.3, transit 0.18 s) and leans into notes from below (scoop=25), the column glides less",
    text: `
. clock        72 4/4
. arrange@song road:2bars song:16bars hum:16bars
. key          gong F#

. caption@c1   "北上太行山，艱哉何巍巍！羊腸坂詰屈，車輪為之摧。 / 樹木何蕭瑟，北風聲正悲。熊羆對我蹲，虎豹夾路啼。" ?song.2-3
. wind@beifeng  0.6 gust=0.15Hz
. drums@step    kit=zhangu vol=0.12 "x.......x.......|................|................" ?song.1-3
. drums@horse   kit=horses vol=0.8 "................................................................|................................................................................................................................x...............................|................................................................" ?song.1-3
. chant@soldier voice=men oct=3 grid=8 human=0.6 rubato=0.3 scoop=25 glide=0.3 vib=0.03 breath=0.2 dyn="mp mf mf mp mf mf mp mp mp mf mf mp mf mf mp p" ipa="${words}" "${tune}" ?song.2-3
. chant@column  voice=men voices=8 oct=3 grid=8 human=0.7 glide=0.2 vib=0.015 breath=0.3 vol=0.5 dyn="p mp" ipa="${words}" "${tune}" ?song.3

*> space       valley size=1.3
>  speaker      0.5
`,
  };
}

// ── zhu-xis-legacy.showcase.js
// 鹿鳴 from the 風雅十二詩譜 that Zhu Xi printed in his 儀禮經傳通解: the eight sounds (八音) of ritual music one by one,
// then together under the sung ode. Rebuilt from Zhao Yue's (赵越) yayue reconstruction (voice on a demucs stem).
{
  // One note to a syllable (一字一音), as the Song lülü notation writes it; gong on D, with the 变徵 (#4) of the old scale.
  // Transcribed by ear-and-machine from the reconstruction's first stanza: the line is approximate.
  const lines = ["1' 6 #4 3", "6 2 1 4", "5 5 7 6", "5 6 1' 5", "5 #4 5 5", "6 3 3 7", "1' 6 6 5", "3 6 2' 1'"];
  const ode = lines.join(" ");
  const two = (i) => `${lines[i]} ${lines[i + 1]}`;
  const words = "jou jou lu miŋ ʂɨ je tʂɨ pʰiŋ wo jou tɕia pin ku sɤ tʂʰwei ʂəŋ tʂʰwei ʂəŋ ku xwaŋ tʂʰəŋ kʰwaŋ ʂɨ tɕiaŋ ʐən tʂɨ xau wo ʂɨ wo tʂou xaŋ";
  // 金声玉振: the bell sounds the first note of each line, the stone chime answers on its last
  const bells = lines.map((l) => `${l.split(" ")[0]} 0 0 0`).join(" ");
  const stones = lines.map((l) => `0 0 0 ${l.split(" ")[3]}`).join(" ");
  SCORES["zhu-xis-legacy:showcase"] = {
    about: "The Deer Cry (鹿鳴), first of the twelve Book of Songs tunes Zhu Xi preserved (風雅十二詩譜), played through the eight sounds of ritual music one at a time, metal, stone, silk, bamboo, gourd and earth, then sung with them all, a bell opening each line and a stone chime closing it",
    heard: "an academy hall of the Song literati, wooden and high-roofed, at a rite of the village wine-drinking (鄉飲酒禮) where the ode was sung to welcome guests: very slow, one note a syllable; the wooden zhu (柷) begins, a bell and a stone chime frame each line, qin and se, panpipes, sheng, xun and chi double the singers, a drum beats softly between the lines, and the tiger-shaped yu (敔) is scraped at the end",
    refs: [
      { title: "Lu Ming 鹿鸣, Confucian ritual song from the Feng Ya Shi'er Shi Pu", who: "Zhao Yue 赵越 and the Yayue Training Institute, China Conservatory of Music (bayin instruments)", url: "https://www.youtube.com/watch?v=yQ4KkaFlA4U" },
    ],
    measured: "mix: gong on D, the line comes to rest on D; pitch set D E F# G G# A B C# (the old scale with both 4 and #4); ~1.5 sung onsets a second with syllables 1–2 s long, so one note to a syllable at about ♩ = 44; bright metal and stone (centroid 1.5 kHz), a full low end from the drum and qin, a long hall tail. Our line is transcribed from a noisy pitch track of the voice stem, so single notes may be wrong; the reconstruction sings in modern Mandarin, as we do. The real rite's instrumentation and tempo are themselves reconstructions",
    text: `
. clock        44 4/4
. arrange@song zhu:1bars bianzhong:2bars bianqing:2bars qin:2bars se:2bars paixiao:2bars sheng:2bars xun:2bars chi:2bars ode:8bars yu:1bars
. key          major D

. caption@c0   "鹿鳴 · 風雅十二詩譜" ?song.1-9
. caption@c1   "呦呦鹿鳴，食野之苹 / 我有嘉賓，鼓瑟吹笙 / 吹笙鼓簧，承筐是將 / 人之好我，示我周行" ?song.10
. drums@zhu      kit=temple vol=2 "................|................|x...x...x......." ?song.1
. bell@bianzhong  oct=4 grid=4 "${two(0)}" ?song.2
. bell@bianqing   oct=5 grid=4 vol=0.7 "${two(2)}" ?song.3
. pluck@guqin     oct=3 grid=4 "${two(4)}" ?song.4
. pluck@se        oct=3 grid=4 vol=1.6 "${two(6)}" ?song.5
. flute@paixiao   oct=5 grid=4 vol=0.35 "${two(0)}" ?song.6
. organ@sheng     oct=4 grid=4 vol=0.6 "${two(2)}" ?song.7
. flute@xun       oct=4 grid=4 vol=0.4 "${two(4)}" ?song.8
. flute@chi       oct=5 grid=4 vol=0.35 "${two(6)}" ?song.9
. chant@singers   voice=men voices=8 oct=3 grid=4 human=0.3 vib=0.008 breath=0.1 dyn="mf" ipa="${words}" "${ode}" ?song.10
. bell@bianzhong2 oct=4 grid=4 vol=0.9 "${bells}" ?song.10
. bell@bianqing2  oct=5 grid=4 vol=0.6 "${stones}" ?song.10
. pluck@guqin2    oct=3 grid=4 vol=1.4 "${ode}" ?song.10
. pluck@se2       oct=3 grid=4 vol=1.2 "${ode}" ?song.10
. flute@paixiao2  oct=5 grid=4 vol=0.25 "${ode}" ?song.10
. organ@sheng2    oct=4 grid=4 vol=0.3 "${ode}" ?song.10
. flute@xun2      oct=4 grid=4 vol=0.2 "${ode}" ?song.10
. drums@bofu      kit=zhangu vol=0.3 "........x...x...|................|................" ?song.10
. drums@yu        kit=temple vol=2 "................|................|x.x.x..........." ?song.11
. bell@last       oct=4 grid=4 "1' - - -" ?song.11

*> space       ancestral size=1.1
>  speaker     0.5
`,
  };
}

